def agent_action(sandbox, agent_body, step_count):
    # Check for time limit or overheating
    if step_count >= 10000 or sandbox.is_overheated():
        return

    current_heat = sandbox.get_heat()
    overheat_limit = sandbox.get_overheat_limit()

    # Check if already overheated
    if current_heat >= overheat_limit:
        return

    # Get current position
    pos = sandbox.get_craft_position()
    x, y = pos

    # Check if target zone is reached
    in_target = 28.0 <= x <= 32.0 and 2.0 <= y <= 5.0
    if in_target:
        return

    # Determine gate passage status
    passed_gate1 = x > 14.0
    passed_gate2 = x > 24.0

    # Determine target based on gate status
    if not passed_gate1:
        target_x, target_y = 13.0, 1.9  # Center of Gate 1
    elif not passed_gate2:
        target_x, target_y = 23.0, 2.4  # Center of Gate 2
    else:
        target_x, target_y = 30.0, 3.0  # Target zone

    # Adjust for gate y ranges if in gate's x range
    if not passed_gate1 and 12.0 <= x <= 14.0:
        if y < 1.0:
            dy = 1.0 - y
        elif y > 2.8:
            dy = 2.8 - y
        else:
            dy = 0.0
    elif not passed_gate2 and 22.0 <= x <= 24.0:
        if y < 1.8:
            dy = 1.8 - y
        elif y > 3.0:
            dy = 3.0 - y
        else:
            dy = 0.0
    else:
        dy = target_y - y

    dx = target_x - x

    # Proportional control with tuning factor
    K = 0.15  # Tuned for stability and heat management
    f1 = K * dx
    f2 = K * dy

    # Calculate thrust magnitude for heat management
    thrust_magnitude = (f1**2 + f2**2)**0.5
    steps_remaining = 10000 - step_count

    if steps_remaining > 0:
        max_allowed = (overheat_limit - current_heat) / steps_remaining
        if thrust_magnitude > max_allowed:
            scale = max_allowed / thrust_magnitude
            f1 *= scale
            f2 *= scale

    # Apply thrust
    sandbox.apply_thrust(f1, f2)

